// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address arg0, address arg3) public {
        vm.assume(arg0 != arg3);

        // Build a clone-style calldata: owner() selector followed by four
        // immutable-arg addresses, then the 2-byte little/big-endian payload length
        // that _getImmutableArgsOffset() expects as the trailing uint16.
        bytes memory payload = abi.encodePacked(arg0, arg3, arg3, arg3);
        bytes memory cd = abi.encodeWithSelector(Cooler.owner.selector, payload);
        // strip ABI padding of the dynamic arg: instead craft raw calldata directly
        cd = abi.encodePacked(Cooler.owner.selector, payload, uint16(payload.length));

        (bool ok, bytes memory ret) = address(c).call(cd);
        assertTrue(ok, "owner() call failed");

        address returned = abi.decode(ret, (address));
        // Rule: owner() always returns the FIRST immutable arg (offset 0x0),
        // never the fourth one (offset 0x3c).
        assertTrue(returned == arg0 && returned != arg3, "owner() must return the arg at offset 0x0");
    }
}
